SELECT jsonb_build_object('customer',(SELECT count(*) FROM app.customer_profiles WHERE id='7e66fac5-ec65-57ba-85c5-8c041cacddc0'),'command',(SELECT count(*) FROM platform.runtime_command_receipt WHERE id IN ('013bcd2a-0d2d-57a1-84b4-23fd70470326','2ef8da1f-1990-5fe4-a2a0-8ede7f85b1d3')), 'history',(SELECT count(*) FROM app.customer_profile_lifecycle_event WHERE customer_profile_id='7e66fac5-ec65-57ba-85c5-8c041cacddc0'),'evidence',(SELECT count(*) FROM platform.owner_mutation_evidence WHERE aggregate_kind='CustomerProfile' AND aggregate_id='7e66fac5-ec65-57ba-85c5-8c041cacddc0'),'outbox',(SELECT count(*) FROM platform.runtime_outbox_message WHERE command_receipt_id IN ('013bcd2a-0d2d-57a1-84b4-23fd70470326','2ef8da1f-1990-5fe4-a2a0-8ede7f85b1d3')),'track_enrollments',(SELECT count(*) FROM app.track_enrollment_receipt WHERE profile_id='7e66fac5-ec65-57ba-85c5-8c041cacddc0'),'coherent',EXISTS(SELECT 1 FROM app.customer_profiles c
 JOIN platform.runtime_command_receipt q ON q.id='013bcd2a-0d2d-57a1-84b4-23fd70470326' AND q.owner_module_id='customer_buyer_profile' AND q.operation='SH-004.v1'
  AND q.subject_scope='CustomerProfile:'||c.id::text AND q.semantic_key='unique-control-same-fingerprint-holder-rollback' AND q.fingerprint='fbb38864c2d4feb8452602413ba68583844d2362bd5602d86d7ed2003751b813'
  AND q.state='committed' AND q.source_revision=0 AND q.result_schema_id='SH-004.v1#/$defs/response' AND q.result_schema_version='1'
  AND q.result_body='{"contract":"SH-004.v1","requestId":"unique-race-same-fingerprint-holder-rollback-a","status":"ok","value":{"customerProfileId":"7e66fac5-ec65-57ba-85c5-8c041cacddc0","userId":"21a01cd9-60db-5cac-b924-f682f19f20ba","lifecycle":"active","sourceToken":"0","receipt":{"owner":"customer_buyer_profile","id":"013bcd2a-0d2d-57a1-84b4-23fd70470326","semanticKey":"unique-control-same-fingerprint-holder-rollback","fingerprint":"fbb38864c2d4feb8452602413ba68583844d2362bd5602d86d7ed2003751b813","sourceToken":"0","recordedAt":"2026-11-17T00:00:00Z"}}}'::jsonb AND q.result_digest=encode(sha256(convert_to(q.result_body::text,'UTF8')),'hex')
 JOIN app.customer_profile_lifecycle_event h ON h.id='7e8fff89-aa3c-5cb3-93c8-b1a4fc4b0fb4' AND h.customer_profile_id=c.id AND h.command_receipt_id=q.id
  AND h.source_revision=0 AND h.from_status IS NULL AND h.to_status=c.status AND h.actor_user_id=c.user_id AND h.name='customer.lifecycle_changed.v1'
 JOIN platform.owner_mutation_evidence e ON e.id='ae17960d-4538-58d1-b1f2-c09601fd97a6' AND e.command_receipt_id=q.id AND e.owner_module_id=q.owner_module_id
  AND e.aggregate_kind='CustomerProfile' AND e.aggregate_id=c.id::text AND e.previous_revision IS NULL AND e.committed_revision=0
  AND e.action=q.operation AND e.decision_ref='customer-controls-v1' AND e.evidence_schema_version='1'
  AND e.evidence_schema_id='urn:workinants:database-review:owner-evidence:v1#/$defs/CustomerProfile'
  AND e.evidence_body='{"schema":"database-owner-evidence.v1","owner":"customer_buyer_profile","model":"CustomerProfile","primaryKey":{"id":"7e66fac5-ec65-57ba-85c5-8c041cacddc0"},"prior":null,"committed":{"id":"7e66fac5-ec65-57ba-85c5-8c041cacddc0","userId":"21a01cd9-60db-5cac-b924-f682f19f20ba","status":"active","revision":"0","privacyGeneration":"0"},"decisionRef":"customer-controls-v1"}'::jsonb AND e.evidence_digest=encode(sha256(convert_to(e.evidence_body::text,'UTF8')),'hex')
 WHERE c.id='7e66fac5-ec65-57ba-85c5-8c041cacddc0' AND c.user_id='21a01cd9-60db-5cac-b924-f682f19f20ba' AND c.status='active' AND c.revision=0 AND c.privacy_generation=0
  AND c.display_name IS NULL AND c.avatar_media_id IS NULL AND c.city IS NULL AND c.state IS NULL AND c.country IS NULL AND c.archived_at IS NULL
  AND q.mutation_transaction_id=c.mutation_transaction_id AND h.mutation_transaction_id=c.mutation_transaction_id AND e.mutation_transaction_id=c.mutation_transaction_id
  AND (SELECT count(*) FROM platform.runtime_outbox_message o WHERE o.command_receipt_id=q.id AND o.producer_owner=q.owner_module_id
   AND o.aggregate_kind='CustomerProfile' AND o.aggregate_id=c.id::text AND o.source_revision=0 AND o.source_generation=0 AND o.schema_version='1'
   AND o.causation_id=q.id::text AND o.correlation_id='unique-race-same-fingerprint-holder-rollback-a' AND o.mutation_transaction_id=c.mutation_transaction_id
   AND o.payload_hash=encode(sha256(convert_to(o.payload::text,'UTF8')),'hex')
   AND ((o.id='d653325e-76ef-5fb5-a58c-7cf3e2e9caa0' AND o.ordinal=0 AND o.kind='event' AND o.name='customer.lifecycle_changed.v1'
    AND o.payload_schema_id='urn:workin-ants:types:v1#/$defs/EventPayload_customer_lifecycle_changed_v1' AND o.payload='{"eventName":"customer.lifecycle_changed.v1","customerProfileId":"7e66fac5-ec65-57ba-85c5-8c041cacddc0","userId":"21a01cd9-60db-5cac-b924-f682f19f20ba","lifecycleRevision":"0","safeState":"active"}'::jsonb)
    OR (o.id='9e865cb1-79f3-53a6-a1c5-cc37e6127595' AND o.ordinal=1 AND o.kind='command' AND o.name='assignDefaultFreeTrack.v1'
    AND o.payload_schema_id='urn:workinants:database-review:foundation-payloads:v1#/$defs/assignDefaultFreeTrackCustomerCommand' AND o.payload='{"sourceOwner":"customer_buyer_profile","userId":"21a01cd9-60db-5cac-b924-f682f19f20ba","track":"customer","customerProfileId":"7e66fac5-ec65-57ba-85c5-8c041cacddc0","sourceCreationRevision":"0","sourceCreationReceipt":"013bcd2a-0d2d-57a1-84b4-23fd70470326","semanticKey":"customer_buyer_profile/7e66fac5-ec65-57ba-85c5-8c041cacddc0/default-free-enrollment/v1"}'::jsonb)))=2));
